SELECT art.project_id 'project.id', pro.name 'project.name', pro.serial_number 'project.serial_number', pro.short_name 'project.short_name', art.monomer_id, mon.`name` monomerName, art.area_id, art.name name, area.`name` areaName, art.id productId, art.serial_number, art.specification, art.material, art.net_weight, art.gross_weight, pri.id printId, pri.workshop_id, shop.NAME workshopName, fac.id factoryId , fac.name factoryName, pri.task_quantity taskQuantity, pri.report_quantity reportQuantity, pri.quantity canReportQuantity, pri.number, pri.operation_id operationId, pri.bool_all_report boolAllReport, us.`name` operationName, pri.bool_assist, pri.task_id 'taskId' FROM mes_building_single_part_artifact_print pri LEFT JOIN tech_artifact art ON art.id = pri.product_id AND art.bool_delete_enum = 0 LEFT JOIN sys_user us ON pri.operation_id = us.id AND us.bool_delete_enum = 0 LEFT JOIN mes_building_workshop shop ON pri.workshop_id = shop.id AND shop.bool_delete_enum = 0 LEFT JOIN contract_project pro ON art.project_id = pro.id LEFT JOIN plan_monomer mon ON art.monomer_id = mon.id LEFT JOIN plan_area area ON area.id = art.area_id LEFT JOIN mes_building_factory fac ON shop.factory_id=fac.id WHERE pri.bool_delete_enum = 0 and (pri.warehousing_type!=1 OR pri.warehousing_type is NULL )
and art.project_id = #{projectId}
AND art.project_id in
#{projectId}
AND art.monomer_id = #{monomerId}
AND art.area_id = #{areaId}
AND art.serial_number LIKE concat('%', #{serialNumber}, '%')

SELECT art.project_id 'project.id', pro.NAME 'project.name', pro.serial_number 'project.serial_number', pro.short_name 'project.short_name', art.monomer_id, mon.`name` monomerName, art.area_id, area.`name` areaName, art.id productId, art.name name, art.serial_number, art.specification, art.material, shop.NAME workshopName, art.net_weight, art.gross_weight, record.print_user_id printUserId, us.`name` printUserName, record.print_quantity printQuantity, ops.`name` operationName, record.create_time printTime FROM mes_building_single_part_artifact_print_record record LEFT JOIN tech_artifact art ON record.product_id = art.id AND art.bool_delete_enum = 0 LEFT JOIN sys_user us ON record.print_user_id = us.id AND us.bool_delete_enum = 0 LEFT JOIN mes_building_workshop shop ON pri.workshop_id = shop.id AND shop.bool_delete_enum = 0 LEFT JOIN contract_project pro ON art.project_id = pro.id LEFT JOIN plan_monomer mon ON art.monomer_id = mon.id LEFT JOIN plan_area area ON area.id = art.area_id WHERE record.bool_delete_enum = 0
AND record.sing_id=#{singId}
and art.project_id = #{projectId}
AND art.project_id in
#{projectId}
AND art.monomer_id = #{monomerId}
AND art.area_id = #{areaId}
AND art.serial_number LIKE concat('%', #{serialNumber}, '%')
AND us.name LIKE concat('%', #{userName}, '%')

        select *
        from mes_building_single_part_artifact_print
        where
        
            
                ( product_id= #{check.id}
                
                    and number in
                    
